INSERT INTO market_meta (market_id,category,resolution_source,resolution_criteria,image_url,updated_ms) VALUES ('0xM1', 'Economics', 'https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm', 'Resolves YES if the FOMC statement released at the September meeting announces a reduction in the target range for the federal funds rate. Resolves NO if the range is unchanged or raised.', NULL, {{NOW_MS}}) ON CONFLICT (market_id) DO UPDATE SET category = EXCLUDED.category, resolution_source = EXCLUDED.resolution_source, resolution_criteria = EXCLUDED.resolution_criteria;
INSERT INTO market_meta (market_id,category,resolution_source,resolution_criteria,image_url,updated_ms) VALUES ('0xM2', 'Crypto', 'https://www.coinbase.com/price/bitcoin', 'Resolves YES if the 23:59 UTC close on <b>Coinbase</b> &amp; the Binance 1m candle both print above $150,000. <script>steal()</script> See [the source](https://example.org/btc) for the candle used. <img src=x onerror=alert(1)>', NULL, {{NOW_MS}}) ON CONFLICT (market_id) DO UPDATE SET category = EXCLUDED.category, resolution_source = EXCLUDED.resolution_source, resolution_criteria = EXCLUDED.resolution_criteria;
INSERT INTO market_meta (market_id,category,resolution_source,resolution_criteria,image_url,updated_ms) VALUES ('0xM3', 'Culture', 'https://example.org/listing-notice', 'Resolves YES if the token is listed on any venue in the named exchange group before the close.', NULL, {{NOW_MS}}) ON CONFLICT (market_id) DO UPDATE SET category = EXCLUDED.category, resolution_source = EXCLUDED.resolution_source, resolution_criteria = EXCLUDED.resolution_criteria;
INSERT INTO market_meta (market_id,category,resolution_source,resolution_criteria,image_url,updated_ms) VALUES ('0xM4', 'Politics', 'https://example.org/governance-record', 'Resolves YES if the motion passes on the recorded vote; abstentions do not count as votes cast.', NULL, {{NOW_MS}}) ON CONFLICT (market_id) DO UPDATE SET category = EXCLUDED.category, resolution_source = EXCLUDED.resolution_source, resolution_criteria = EXCLUDED.resolution_criteria;
INSERT INTO market_meta (market_id,category,resolution_source,resolution_criteria,image_url,updated_ms) VALUES ('0xM5', 'Politics', 'https://example.org/mayoral-return', 'Resolves YES for the candidate certified by the returning officer. negRisk: exactly one outcome can resolve YES, and the others resolve NO together.', NULL, {{NOW_MS}}) ON CONFLICT (market_id) DO UPDATE SET category = EXCLUDED.category, resolution_source = EXCLUDED.resolution_source, resolution_criteria = EXCLUDED.resolution_criteria;
INSERT INTO market_meta (market_id,category,resolution_source,resolution_criteria,image_url,updated_ms) VALUES ('0xM6', 'Politics', 'https://example.org/closed-market', 'This market is closed and its outcome is recorded; the page keeps rendering it because links to resolved markets must not 404.', NULL, {{NOW_MS}}) ON CONFLICT (market_id) DO UPDATE SET category = EXCLUDED.category, resolution_source = EXCLUDED.resolution_source, resolution_criteria = EXCLUDED.resolution_criteria;
INSERT INTO market_meta (market_id,category,resolution_source,resolution_criteria,image_url,updated_ms) VALUES ('0xM9', 'Politics', 'https://example.org/recount', 'Resolves NO. The book is one-sided because every remaining holder of YES is asking to leave; a screen that renders this as broken is a screen that will be blamed for the market''s outcome.', NULL, {{NOW_MS}}) ON CONFLICT (market_id) DO UPDATE SET category = EXCLUDED.category, resolution_source = EXCLUDED.resolution_source, resolution_criteria = EXCLUDED.resolution_criteria;
